head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst70010";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst70010.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_listClssCd", fn: function(){ return ((dma_corpInfo.get("listClssCd") ?? (() => { throw new Error("unresolved:" + "corpInfo.listClssCd"); })()) !== '31'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const ddtt = $(document).find("h1[id=title]");
        ddtt.setLabel("합병상장법인 상세");
        await scwin.fnInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst70010.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tabName_onclick
 * @description tabName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tabName_onclick = async function(e){
    try {
        await scwin.fnTabMenu(0)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst70010.tabName_onclick' }); }
};

/**
 * @method
 * @name tabName_2_onclick
 * @description tabName_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tabName_2_onclick = async function(e){
    try {
        await scwin.fnTabMenu(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst70010.tabName_2_onclick' }); }
};

/**
 * @method
 * @name tabName_3_onclick
 * @description tabName_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tabName_3_onclick = async function(e){
    try {
        await scwin.fnTabMenu(2)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst70010.tabName_3_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/listinvstg/listcomdetail.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnPopClose
 * @description fn Pop Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnPopClose = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    await scwin.fnTabMenu("0");
};

/**
 * @method
 * @name fnTabMenu
 * @description fn Tab Menu 처리
 * @param {*} menuIdx menuIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnTabMenu = async function (menuIdx) {
    $(document).find("li[id=tabName]").each(function(index) {
            if ($(this).hasClass("active")) {
                $(this).removeClass("active");
            }
            if (index === menuIdx) {
                $(this).addClass("active");
            }
    });
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("menuIndex", menuIdx);
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    const vMenuIndex = ($c.util.getComponent("dma_fnSearchAjaxsubmitReq").get("menuIndex") || '');
    let vMethod = "";
    if (vMenuIndex === "0") {
        vMethod = "searchListComOvrvwDetail";
    } else {
        if (vMenuIndex === "1") {
            vMethod = "searchListComFncContnDetail";
        } else {
            if (vMenuIndex === "2") {
                vMethod = "searchListComPubofrDetail";
            } else {
                return;
            }
        }
    }
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", vMethod);
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#tabContents").empty().append(data);
};
